package com.hljzjx.classroom.reviewdraw;
import java.util.*;
import android.content.Context;
import android.os.Handler;
import android.view.View;
import android.widget.TextView;
import com.hailiang.common.util.AppRuntimeData;
import com.hailiang.handwrite.bean.PathInfo;
import com.hailiang.handwrite.serialize.PathInfoSerializer;
import com.hailiang.handwrite.widget.HandwriteView;
import com.hailiang.xxb.room.server.*;
import com.hailiang.xxb.room.server.entity.discussion.*;
import com.nice.room.ui.roomlive.fragment.discussion.*;
import com.nice.room.ui.roomlive.tool.*;
import kotlin.Unit;
import kotlin.jvm.functions.Function0;
public final class ReviewDrawingTest {
 static int checks,photos;static void ok(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static final class Page {DiscussionFragment f=new DiscussionFragment();Context c=new Context();View root=new View(c);HandwriteView h=new HandwriteView(c);RoomToolBarView t=new RoomToolBarView(c);TextView status=new TextView(c);Page(){root.add("handwrite",h);root.add("handwrite_toolbar",t);root.add("tv_countdown",status);f.root=root;t.photo=new Function0<Unit>(){public Unit invoke(){photos++;return Unit.INSTANCE;}};}void refresh(){ReviewDrawing.refresh(f);}List<FunctionToolItemInfo> items(){List<FunctionToolItemInfo> list=new ArrayList<FunctionToolItemInfo>();ReviewDrawing.append(list,t.state);return list;}void start(){items().get(0).click.invoke(null);}}
 static PathInfo path(long u,long id){PathInfo p=new PathInfo();p.userMark=u;p.pathID=id;p.pointsList=new ArrayList<Object>();p.pointsList.add(new Object());return p;}
 static GroupDiscussionDetail detail(long group,PathInfo...paths){GroupDiscussionDetail d=new GroupDiscussionDetail();d.group=group;DiscussionStroke member=new DiscussionStroke();for(PathInfo p:paths)member.records.add(new PathInfoSerializer().serialize(p));d.strokes.add(member);return d;}
 static DiscussionRepository.Call read(int index){return DiscussionRepository.reads.get(index);}
 static void finish(int index,GroupDiscussionDetail d){read(index).finish(new Result.Success<GroupDiscussionDetail>(d));Handler.tick(0);}
 static void normal(){Page p=new Page();p.f.history=false;p.t.visibility=View.GONE;p.refresh();ok(p.items().isEmpty(),"live toolbar untouched");ok(p.t.visibility==View.GONE,"history code does not show live toolbar");ok(!ReviewDrawing.capture(p.f.model,20,30,path(7,1)),"live append follows original path");ok(ReviewDrawing.photoResult(p.f)==0,"live photo guard original");}
 static void history(){Page p=new Page();p.refresh();ok(DiscussionRepository.reads.size()==1&&read(0).history,"native historical DB endpoint selected");ok(p.t.visibility==View.VISIBLE&&!p.t.clearHidden&&!p.t.colorHidden&&!p.t.graphHidden,"full native toolbar made visible");ok(p.items().size()==2&&p.items().get(0).label.equals("继续画"),"native action items");ok(!p.h.enabled&&!p.h.canDraw,"no editing before readback");p.start();finish(0,detail(30,path(8,1)));ok(p.h.enabled&&p.h.canDraw&&p.t.selected==DrawingTool.BRUSH,"continue request during load enabled when ready");ok(p.h.paths.size()==1&&p.h.paths.get(0).userMark==8,"original members ink retained");p.t.state.enabled=false;p.h.canDraw=false;p.refresh();ok(p.t.state.enabled&&p.h.canDraw,"native state refresh restores history toolbar and write mode");
  ok(ReviewDrawing.capture(p.f.model,20,30,path(7,2)),"history append intercepted");Handler.tick(1999);ok(DiscussionRepository.appends.isEmpty(),"debounced upload");Handler.tick(1);ok(DiscussionRepository.appends.size()==1,"automatic upload started");Map body=(Map)DiscussionRepository.appends.get(0).body;ok(body.get("groupDiscussionId").equals(20L)&&body.get("groupDiscussionGroupId").equals(30L)&&body.get("userId").equals(7L)&&body.get("userType").equals(1),"exact native request identity");ok(((List)body.get("recordValueList")).size()==1,"other user's original ink not retransmitted");
  DiscussionRepository.appends.get(0).finish(new Result.Failure("服务端拒绝"));Handler.tick(0);ok(p.status.text.equals("服务端拒绝"),"native business failure displayed");ok(ReviewDrawing.merge(p.f,Collections.<PathInfo>emptyList()).size()==2,"native empty-load event retains original plus failed draft");
  p.items().get(1).click.invoke(null);ok(DiscussionRepository.appends.size()==2,"retry through native toolbar");DiscussionRepository.appends.get(1).finish(new Result.Success<Boolean>(true));Handler.tick(0);finish(1,detail(30,path(8,1)));ok(p.status.text.contains("尚未回读"),"acceptance is not historical persistence");
  p.items().get(1).click.invoke(null);finish(2,detail(30,path(8,1),path(7,2)));ok(p.status.text.contains("回读确认"),"historical persistence reflected");ok(ReviewDrawing.merge(p.f,Collections.<PathInfo>emptyList()).size()==2,"confirmed ink persists through subsequent native refresh");
  int before=DiscussionRepository.appends.size();ReviewDrawing.capture(p.f.model,20,30,path(8,5));Handler.tick(2000);ok(DiscussionRepository.appends.size()==before,"cannot upload someone else's ink");
  p.t.photo.invoke();ok(photos==1&&ReviewDrawing.photoResult(p.f)==1,"original camera function and ended-history result allowed");ok(ReviewDrawing.photoResult(p.f)==-1,"photo result cannot be replayed");
  p.t.photo.invoke();p.f.group=31;p.refresh();ok(ReviewDrawing.photoResult(p.f)==-1,"old crop result cannot upload to newly-selected group");ok(!p.h.canDraw,"group switch returns to read mode");ok(read(3).g==31,"new group read identity");finish(3,detail(31,path(9,3)));ok(p.h.paths.size()==1&&p.h.paths.get(0).userMark==9,"new group replaces old canvas, no cross-group overlay");
  p.start();ReviewDrawing.capture(p.f.model,20,31,path(7,9));p.f.group=32;p.refresh();finish(4,detail(32));Handler.tick(2000);Map old=(Map)DiscussionRepository.appends.get(before).body;ok(old.get("groupDiscussionGroupId").equals(31L),"queued upload remains bound to former group");ReviewDrawing.detach(p.f);ok(p.items().isEmpty(),"destroyed view releases native toolbar registration");
 }
 static void staleRead(){Page p=new Page();p.f.group=40;p.refresh();int first=DiscussionRepository.reads.size()-1;p.f.group=41;p.refresh();int next=DiscussionRepository.reads.size()-1;finish(next,detail(41,path(7,41)));finish(first,detail(40,path(7,40)));ok(p.h.paths.size()==1&&p.h.paths.get(0).pathID==41,"old read cannot replace current group");p.f.group=42;p.refresh();int failed=DiscussionRepository.reads.size()-1;finish(failed,detail(999));ok(!p.h.canDraw,"mismatched group response never enables writing");p.start();int retry=DiscussionRepository.reads.size()-1;read(retry).finish(new Result.Failure("未授权"));Handler.tick(0);ok(!p.h.canDraw&&p.status.text.equals("未授权"),"read permission failure is authoritative");ReviewDrawing.detach(p.f);}
 static void account(){Page p=new Page();p.f.group=50;p.refresh();int read=DiscussionRepository.reads.size()-1;AppRuntimeData.uid=99;finish(read,detail(50,path(7,50)));ok(!p.h.canDraw,"account change during fetch cannot enable editing");int sends=DiscussionRepository.appends.size();ReviewDrawing.capture(p.f.model,20,50,path(7,51));Handler.tick(2000);ok(DiscussionRepository.appends.size()==sends,"no history upload under switched account");ReviewDrawing.detach(p.f);AppRuntimeData.uid=7;}
 static void reopenDuringUpload(){Page old=new Page();old.f.group=70;old.refresh();finish(DiscussionRepository.reads.size()-1,detail(70));old.start();ReviewDrawing.capture(old.f.model,20,70,path(7,70));Handler.tick(2000);DiscussionRepository.Call sent=DiscussionRepository.appends.get(DiscussionRepository.appends.size()-1);ReviewDrawing.detach(old.f);Page next=new Page();next.f.group=70;next.refresh();int current=DiscussionRepository.reads.size()-1;sent.finish(new Result.Success<Boolean>(true));Handler.tick(0);ok(DiscussionRepository.reads.size()-1==current,"late upload ack does not supersede initial page load");finish(current,detail(70,path(7,70)));next.start();ok(next.h.canDraw&&next.h.paths.size()==1,"reopened history completes loading and can draw");ReviewDrawing.detach(next.f);}
 static void direct(){Page p=new Page();p.f.group=60;DiscussionRepository.direct=new Result.Success<GroupDiscussionDetail>(detail(60));p.refresh();Handler.tick(0);p.start();ok(p.h.canDraw,"suspend bridge supports immediate return");DiscussionRepository.direct=new Result.Success<Boolean>(true);ReviewDrawing.capture(p.f.model,20,60,path(7,60));Handler.tick(2000);ok(p.status.text.contains("不匹配"),"invalid immediate readback is reported instead of confirmed");DiscussionRepository.direct=null;ReviewDrawing.detach(p.f);}
 public static void main(String[] args){normal();history();staleRead();account();reopenDuringUpload();direct();System.out.println("PASS ReviewDrawing: "+checks+" executable adapter assertions (API fakes; no Android/backend runtime)");}
}
